#!/usr/bin/env python3
"""Prepare the unaccepted nine-historian research packet; never apply it."""
import json
from pathlib import Path
P=Path(__file__).resolve().parent
ROOT=P.parents[2]
DAY='2026-10-25'; PREFIX='rh188_'
G=json.loads((ROOT/'historiography-1920-2000.json').read_text())
Q=json.loads((ROOT/'data/field-research/remaining-canon-2026-10-25/classification-identity-review/eligible-historian-queue.json').read_text())['records']
PEOPLE={p['id']:p for p in G['people']};NODES={n['id']:n for n in G['nodes']}
S={};D={};L={}
def dump(path,value):
 path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def source(key,title,url,note,metadata=False):
 sid=PREFIX+key;S[sid]={'id':sid,'title':title,'citation':title,'url':url,'verification':{'status':'bibliographic_metadata_checked' if metadata else 'supporting_page_checked','checked_on':DAY,'note':note}};return sid
def event(year,title,sids,note,kind='publication',track='contributions'):
 return {'label':title,'kind':kind,'track':track,'date':{'year':year,'precision':'year'},'source_ids':['graph:'+s for s in sids],'support':note}
def edge(target,label,note,sids,kind='contribution'):
 return {'target':target,'relationship':label,'evidence_note':note,'source_ids':sids,'relationship_kind':kind}
def life(pid,status,sids,birth=None,death=None,precise_birth=None,precise_death=None,limits=''):
 sources=[]
 for sid,loc,support in sids:
  ss=S[sid];sources.append({'url':ss['url'],'title':ss['title'],'locator':loc,'support':support,'checked_on':DAY,'check_scope':ss['verification']['note']})
 r={'person_id':pid,'label':next(q['name'] for q in Q if q['resolved_person_id']==pid),'status':status,'checked_on':DAY,'identity_rationale':next(q['identity_pattern'] for q in Q if q['resolved_person_id']==pid),'sources':sources,'confidence':'high' if status=='deceased' else 'positive_recent_evidence_with_timing_limit','limits':limits+' Life metadata creates no work, career or influence interval.'}
 if birth:r.update(birth_year=birth,birth_precision='day' if precise_birth else 'year')
 if death:r.update(death_year=death,death_precision='day' if precise_death else 'year')
 if precise_birth:r['birth_date']=precise_birth
 if precise_death:r['death_date']=precise_death
 L[pid]=r

def bio(pid,description,events,edges,scope,roster,addenda=None):
 q=next(q for q in Q if q['resolved_person_id']==pid);new=pid not in PEOPLE
 assert pid not in NODES
 if new:
  assert not any(p['label'].casefold()==q['name'].casefold() for p in PEOPLE.values())
 pu={'id':pid,'node_id':pid}
 if new:pu.update(new=True,label=q['name'],identity_note=q['identity_pattern']+' Historical-research classification retains interdisciplinary roles. No external QID assigned.')
 sids=list(dict.fromkeys(s for e in events for s in [x.removeprefix('graph:') for x in e['source_ids']]))
 sids=list(dict.fromkeys(sids+[s for e in edges for s in e['source_ids']]+[sid for sid in S if sid.startswith(PREFIX+pid.split('_')[0]+'_life')]))
 for i,e in enumerate(events,1):e['id']=PREFIX+pid+'_w'+str(i)
 for i,e in enumerate(edges,1):e.update(proposal_id=PREFIX+pid+'_e'+str(i),source=pid,type='critique' if e['relationship_kind']=='critique' else 'connection',directed=True,classification_basis='editorial_review')
 countnote=('The exact frozen first-author key '+q['source_key']+' has '+str(q['frozen_dated_key_count'])+' dated dissertation appearances; this retains the reviewed provisional screening qualification and does not verify every fragment or imply influence.') if pid!='steven_hahn' else 'Four positively identified book keys yield a deduplicated eligibility lower bound of103 dated dissertations. The mixed raw key P:hahn|steven c has121, which is not accepted as a clean person total or as authority evidence; Steven C.Hahn is distinct.'
 node={'id':pid,'label':q['name'],'layer':'historians','entry_kind':'person','entry_type':'Individual historian','period':None,'hunt_core_paradigm':False,'date_label':' · '.join(str(e['date']['year'])+' '+e['label'].split(':')[0] for e in events[:3]),'description':description,'representative_figures_and_works':'; '.join(e['label']+' ('+str(e['date']['year'])+')' for e in events)+'.','source_ids':sids,'scope_note':scope+' '+countnote+' Complete monographs remain unread except the specified selected passages. Existing identities, collective relationships, roster prose and source qualifications remain intact. No continuous career or influence interval is inferred.','chronology':{'version':1,'label':'Selected publication and edition facts','selection_note':'Selected works and manifestations, not a complete bibliography or career interval.','events':events,'intervals':[],'continuation':{'status':'not_asserted','basis':'Selected dated works establish neither continuous activity nor an ending.'},'interpretation':'Dates and credits use bibliographic witnesses; substantive connections use the explicitly bounded primary passages.','prepared_on':DAY,'editorial_record':'data/production-batches/person-entries-1.188/acceptance.json'}}
 ra=[]
 for target,context,works,srcs,edgeindex in roster:
  assert not any(r['person_id']==pid for r in NODES[target].get('representative_people',[]))
  ra.append({'node':target,'proposal_id':edges[edgeindex]['proposal_id'],'row':{'person_id':pid,'role':'historian','context':context,'works':works,'source_ids':srcs,'basis':'source_review'}})
 draft={'status':'proposal_for_review','prepared':DAY,'review_status':'needs_independent_review','node':node,'people_update':pu,'proposed_edges':edges,'new_sources':[],'roster_additions':ra,'source_addenda':addenda or {},'reading_bridge_qualification':{'source_key':q['source_key'],'frozen_dated_key_count':q['frozen_dated_key_count'],'eligibility_count':q['eligibility_count'],'eligibility_count_scope':q['eligibility_count_scope'],'identity_pattern':q['identity_pattern']}}
 D[pid]=draft

# Michel de Certeau: original dates, scientific editor credit, and translation distinct.
