bio('alexis_de_tocqueville','Alexis de Tocqueville investigated democratic society and the historical conditions of revolutionary change while also writing and acting as a political thinker. De la démocratie en Amérique appeared in two parts; L’Ancien Régime et la Révolution returned to prerevolutionary France. In its preface he explains his use of cahiers, provincial records and administrative archives, asking how practices and social relations survived apparent rupture. His study is an earlier historical inquiry into power and society, not membership in a twentieth-century historiographical school.',[event(1835,'De la démocratie en Amérique — first part',[td],'Firstoriginalpart1835;secondpart1840. OriginalFrenchpartsnottwoEnglishreissues.'),event(1840,'De la démocratie en Amérique — second part',[td],'Secondoriginalpart1840;eachpartoriginallycomprisedtwovolumes.'),event(1856,'L’Ancien Régime et la Révolution',[tp],'Original1856publication;readprefaceinsecondeditiondated1856. Latertranslationsnotredatedoriginal.')],[edge('political','Investigates administrative continuity across revolutionary rupture','Avant-propos5–12 asks how habitsandinstitutionsfromthemonarchypersistedafter1789;thisearlierhistoricalresourceisnotlabelledmembershipinmodernPoliticalHistory.',[tp]),edge('social','Uses administrative archives to investigate relations among classes and everyday governance','Avant-propos7–10 describesmovingbeyondcelebratedwritersandpublicfigures towardinstitutionalpractices,socialrelationsandprovincialarchives. ThisisTocqueville’sresearchprogramme,not aclaimthat everyarchivalvoiceisrepresentative.',[tp])],'Read only1856Avant-propos5–12; DemocracybodyandremainingOldRegimeunread. Critical/social connections describeanearlierhistoricalprogramme, not twentieth-century schoolmembership. CoauthoredpenitentiaryreportwithGustavedeBeaumontisnot silentlytreatedassoleauthoredorassignedtheAcademie’sunverified1832date.',[('political','An earlier inquiry into continuities of institutions and governing practice across the French Revolution.','L’Ancien Régime et la Révolution(1856),Avant-propos5–12',[tp],0)])
